sql.append(f"INSERT INTO studio_guided_sessions(session_id,test_id,principal_id,scope_hash,state,expires_at,document) VALUES({q(sid)},{q(doc['testId'])},'reviewer',{q(sh)},'OBSERVING',{q(expiry)},{j(doc)});")
